import{_ as e,o as i,c as a,a2 as n}from"./chunks/framework.CsFjlSKj.js";const g=JSON.parse('{"title":"2. Files & Directories","description":"","frontmatter":{},"headers":[],"relativePath":"linux/files-and-directories.md","filePath":"linux/files-and-directories.md"}'),t={name:"linux/files-and-directories.md"};function o(r,s,l,d,h,c){return i(),a("div",null,[...s[0]||(s[0]=[n(`<h1 id="_2-files-directories" tabindex="-1">2. Files &amp; Directories <a class="header-anchor" href="#_2-files-directories" aria-label="Permalink to &quot;2. Files &amp; Directories&quot;">​</a></h1><p>Linux organizes data in a single, hierarchical directory structure starting from the root directory (<code>/</code>).</p><h2 id="the-filesystem-hierarchy-standard-fhs" tabindex="-1">The Filesystem Hierarchy Standard (FHS) <a class="header-anchor" href="#the-filesystem-hierarchy-standard-fhs" aria-label="Permalink to &quot;The Filesystem Hierarchy Standard (FHS)&quot;">​</a></h2><p>The FHS defines the directory structure and directory contents in Linux distributions. Knowing where things belong is critical.</p><ul><li><code>/bin</code> &amp; <code>/usr/bin</code>: Essential user command binaries (e.g., <code>ls</code>, <code>grep</code>).</li><li><code>/sbin</code> &amp; <code>/usr/sbin</code>: System binaries intended for the root user (e.g., <code>fdisk</code>, <code>iptables</code>).</li><li><code>/etc</code>: Host-specific system configuration files. (No executable binaries should be here).</li><li><code>/var</code>: Variable data files, such as logs (<code>/var/log</code>), databases, and website content (<code>/var/www</code>).</li><li><code>/tmp</code>: Temporary files. Often cleared upon reboot.</li><li><code>/home</code>: User home directories containing personal configurations (like <code>~/.bashrc</code>).</li><li><code>/proc</code> &amp; <code>/sys</code>: Virtual filesystems representing Kernel and Process states.</li></ul><h2 id="inodes-and-links" tabindex="-1">Inodes and Links <a class="header-anchor" href="#inodes-and-links" aria-label="Permalink to &quot;Inodes and Links&quot;">​</a></h2><p>In Linux, a filename is just a pointer. The actual metadata (permissions, ownership, physical disk location) is stored in a data structure called an <strong>inode</strong>.</p><h3 id="hard-links" tabindex="-1">Hard Links <a class="header-anchor" href="#hard-links" aria-label="Permalink to &quot;Hard Links&quot;">​</a></h3><p>A hard link creates a new filename that points to the exact same inode as the original file. If you delete the original filename, the data still exists until the last hard link is deleted.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file1.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hardlink.txt</span></span></code></pre></div><h3 id="soft-symbolic-links" tabindex="-1">Soft (Symbolic) Links <a class="header-anchor" href="#soft-symbolic-links" aria-label="Permalink to &quot;Soft (Symbolic) Links&quot;">​</a></h3><p>A soft link is a special file that acts as a shortcut. It points to the <em>filename</em> of another file, not its inode. If the original file is deleted, the soft link becomes &quot;broken&quot;.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/nginx/sites-available/default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/nginx/sites-enabled/default</span></span></code></pre></div><h2 id="permissions-and-ownership" tabindex="-1">Permissions and Ownership <a class="header-anchor" href="#permissions-and-ownership" aria-label="Permalink to &quot;Permissions and Ownership&quot;">​</a></h2><p>Linux security is heavily dependent on file permissions. Every file has an <strong>Owner</strong> user and an <strong>Owner Group</strong>.</p><p>Permissions are divided into three categories: <strong>User (u)</strong>, <strong>Group (g)</strong>, and <strong>Others (o)</strong>. For each, you can assign <strong>Read (r - 4)</strong>, <strong>Write (w - 2)</strong>, and <strong>Execute (x - 1)</strong>.</p><h3 id="viewing-permissions" tabindex="-1">Viewing Permissions <a class="header-anchor" href="#viewing-permissions" aria-label="Permalink to &quot;Viewing Permissions&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/passwd</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example output: -rw-r--r-- 1 root root 2.3K Jan  1 12:00 /etc/passwd</span></span></code></pre></div><p>The string <code>-rw-r--r--</code> translates to:</p><ul><li><code>-</code>: Regular file</li><li><code>rw-</code>: User (root) can read and write. (4+2=6)</li><li><code>r--</code>: Group (root) can read. (4)</li><li><code>r--</code>: Others can read. (4) This is octal permission <code>644</code>.</li></ul><h3 id="changing-permissions-chmod" tabindex="-1">Changing Permissions (<code>chmod</code>) <a class="header-anchor" href="#changing-permissions-chmod" aria-label="Permalink to &quot;Changing Permissions (\`chmod\`)&quot;">​</a></h3><p>You can use symbolic or octal modes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Octal mode (Give User full access, Group and Others read/execute)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Symbolic mode (Add execute permission for everyone)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span></span></code></pre></div><h3 id="changing-ownership-chown" tabindex="-1">Changing Ownership (<code>chown</code>) <a class="header-anchor" href="#changing-ownership-chown" aria-label="Permalink to &quot;Changing Ownership (\`chown\`)&quot;">​</a></h3><p>Only the root user can change the owner of a file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change owner to &#39;alice&#39; and group to &#39;developers&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice:developers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/html</span></span></code></pre></div>`,26)])])}const k=e(t,[["render",o]]);export{g as __pageData,k as default};
